pub type Celsius = Float64;
pub type Fahrenheit = Float64;

fn c_to_f(c: Celsius) -> Fahrenheit {
  return (c * 9.0 / 5.0 + 32.0) as Fahrenheit;
}

impl From[Float64] for Celsius {
  fn from(v: Float64) -> Celsius { return v; }
}

fn main() -> Int {
  let freezing: Celsius = 0.0.into();
  let f: Fahrenheit = c_to_f(freezing);
  return f as Int;
}
